scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).isClientOnly()) {
        return;
    }
    var smallTables = global.EcsConfig.getList('gr.small_tables', []);
    var hits = new global.EcsGlideRecord(new global.EcsAst(engine.rootNode)).unrestrictedQueries(smallTables);
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-GR-001',
        title: 'GlideRecord query with no conditions',
        recommendation: 'Add query conditions for the records actually needed. To read one record use get() or ' +
            'setLimit(1); to count use GlideAggregate. If the table is small by design, add it to the system ' +
            'property ecs.gr.small_tables; otherwise mute this finding with a reason.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
